import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import type { Db } from './client';

/**
 * Committed SQL migrations generated by drizzle-kit (`pnpm db:generate`).
 * `HMIS_MIGRATIONS_DIR` overrides the location for bundled builds (worker image).
 */
export const MIGRATIONS_FOLDER =
  process.env.HMIS_MIGRATIONS_DIR ?? fileURLToPath(new URL('../migrations', import.meta.url));

export async function runMigrations(db: Db, migrationsFolder = MIGRATIONS_FOLDER): Promise<void> {
  await migrate(db, { migrationsFolder, migrationsSchema: 'drizzle' });
}
